import csv
import sqlite3

STEPS = ["install", "tutorial_complete", "first_match", "purchase"]
PLATFORMS = ["pc", "steamdeck"]
DB = "analytics.db"


def funnel_counts(conn: sqlite3.Connection, platform: str) -> list[int]:
    """Greedy chain: earliest install, then each next step's earliest event at or after it."""
    users = [
        r[0]
        for r in conn.execute(
            "select user_id from users where platform = ? and coalesce(is_test, 0) = 0",
            (platform,),
        )
    ]
    marks: dict[str, list[str]] = {}
    for name in STEPS:
        marks[name] = []
    valid = set(users)
    for uid, name, ts in conn.execute(
        "select user_id, name, ts from events where name in (?,?,?,?) order by user_id, ts",
        STEPS,
    ):
        if uid in valid and name in marks:
            marks[name].append((uid, ts))

    per_user: dict[str, list[str | None]] = {uid: [None] * len(STEPS) for uid in users}
    for idx, name in enumerate(STEPS):
        by_user: dict[str, list[str]] = {}
        for uid, ts in marks[name]:
            by_user.setdefault(uid, []).append(ts)
        for uid, slots in per_user.items():
            cands = by_user.get(uid)
            if not cands:
                continue
            if idx == 0:
                slots[0] = cands[0]
                continue
            prev = slots[idx - 1]
            if prev is None:
                continue
            for ts in cands:
                if ts >= prev:
                    slots[idx] = ts
                    break

    counts = [0] * len(STEPS)
    for slots in per_user.values():
        # steps are filled contiguously from install by construction
        for i, ts in enumerate(slots):
            if ts is None:
                break
            counts[i] += 1
    return counts


def ratio(curr: int, prev: int) -> float:
    return 1.0 if prev == 0 else curr / prev


def main() -> None:
    conn = sqlite3.connect(DB)
    rows = []
    for platform in PLATFORMS:
        counts = funnel_counts(conn, platform)
        prev = None
        for step, n in zip(STEPS, counts):
            conv = 1.0 if prev is None else ratio(n, prev)
            rows.append((platform, step, n, f"{conv:.4f}"))
            prev = n
        print(platform, counts)
    with open("funnel.csv", "w", newline="", encoding="utf-8") as fh:
        w = csv.writer(fh)
        w.writerow(["platform", "step", "users", "conv_from_prev"])
        w.writerows(rows)
    print(open("funnel.csv").read())


if __name__ == "__main__":
    main()
